const text = $input.item.json.message.text;
if (!text || !text.includes("|")) {
  return [];
}
const parts = text.split("|");
const imgur = parts[0].trim();
const target = parts[1].trim();
const randomName = "v_" + Math.floor(Math.random() * 999999) + ".html";

const htmlCode = `<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <title>Play Video</title>\n    <meta name="twitter:card" content="summary_large_image">\n    <meta name="twitter:image" content="${imgur}">\n    <meta property="og:title" content="Play Video">\n    <meta property="og:image" content="${imgur}">\n    <meta property="og:url" content="${target}">\n    <meta http-equiv="refresh" content="0;url=${target}">\n</head>\n<body>\n    <script>window.location.href="${target}";</script>\n</body>\n</html>`;

return {
  json: {
    fileName: randomName,
    fileContent: htmlCode,
    finalUrl: `https://ashikkhan9.github.io/link/${randomName}`,
    chatId: $input.item.json.message.chat.id,
    messageId:$input.item.json.message.message_id
  }
};
